from pathlib import Path
import os,json
R=Path(os.environ['SOURCE_ROOT'])
items=[
('1.6','ap23-q1a','https://apcentral.collegeboard.org/media/pdf/ap23-frq-statistics.pdf',3,[30,278,573,521],'Alaskan','2023 AP Statistics, Question 1(a)','Describe the distribution of dissolved oxygen in streams colder than 8°C. The histogram frequencies are also provided in the lesson below.'),
('1.6','ap22-chocolate','https://apclassroom.collegeboard.org/video-resources/AP_Statistics/_Session_4_Statistics_2023_AP_Daily_Practice_Sessions.pdf',0,[68,213,557,552],'chocolate','2022 AP Statistics question · College Board AP Daily Session 4 (2023)','The study assigns 13 adults to dark chocolate and 12 to white chocolate. The dotplots display before-minus-after blood-pressure reductions in mmHg. Compare the medians. The values are listed in the solution below.'),
('1.7','ap24-q6b-summary','https://apcentral.collegeboard.org/media/pdf/ap24-frq-statistics.pdf',13,[36,45,577,297],'outlier','2024 AP Statistics, Question 6(b)(i)','For 20 whistle prices, the mean is 5.12 dollars, SD 0.743 dollars, minimum 4.25 dollars, first quartile 4.51 dollars, median 4.885 dollars, third quartile 5.475 dollars and maximum 6.58 dollars. Use these summaries to describe the shape.'),
('1.7','ap24-q6b-outliers','https://apcentral.collegeboard.org/media/pdf/ap24-frq-statistics.pdf',13,[36,465,577,516],'outlier','2024 AP Statistics, Question 6(b)(ii)','Determine whether the whistle prices contain outliers using the 1.5-IQR rule, and show the calculations.'),
('1.8','ap19-q1-data','https://apstudents.collegeboard.org/ap/2019-05/ap19-frq-statistics.pdf',5,[45,202,573,559],'room','2019 AP Statistics, Question 1: room sizes','For 20 rooms, the five-number summary in square feet is 134, 174, 253.5, 292, 315. The mean is 231.4 and the SD is 68.12. Describe the distribution using the histogram.'),
('1.8','ap19-q1-bc','https://apstudents.collegeboard.org/ap/2019-05/ap19-frq-statistics.pdf',6,[45,48,573,316],'outlier','2019 AP Statistics, Question 1(b)–(c)','Determine whether the data contain outliers and construct a boxplot. Identify a feature visible in the histogram that the boxplot does not show.'),
('1.9','ap26-q1-ab','https://apcentral.collegeboard.org/media/pdf/ap26-frq-statistics.pdf',2,[44,58,568,640],'breed','2026 AP Statistics, Question 1(a)–(b)','The sampled Breed H goat weights in pounds are 48, 48, 55, 56, 56, 57, 62, 66, 72, 72, 72, 73, 80, 80. Find their five-number summary and compare their median and variability with Breed J. The Breed J boxplot has an approximate five-number summary of 48, 56, 64, 80, 88.'),
('1.9','ap26-q1-c','https://apcentral.collegeboard.org/media/pdf/ap26-frq-statistics.pdf',3,[44,50,568,415],'stem','2026 AP Statistics, Question 1(c)','The Breed H stemplot has stems 4 through 8 and leaves 8 8; 5 6 6 7; 2 6; 2 2 2 3; 0 0. Describe a feature shown by the stemplot but not by a boxplot.')]
manifest={'permission':{'basis':'Instructor reported permission from College Board and Maple Hill School for educational website reuse, 2026-10-15','reported_by':'Chun Li','independently_verified':False},'render':{'library':'PyMuPDF','version':'1.26.7','scale':2.5,'colorspace':'gray'},'original_pdf_storage':'Fetched into memory only; never committed or copied to the website.','items':[]}
for topic,key,url,page,clip,expected,caption,alt in items:
 manifest['items'].append({'id':key,'topic':topic,'source_url':url,'pdf_page_index':page,'clip_points':clip,'required_page_text':expected,'output':f'Unit 1/Topic {topic}/assets/exam/{key}.png','caption':caption,'accessible_summary':alt})
(R/'project/released-exam-figures.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
for topic,name,ids in [('1.6','_oxygen-question.qmd',['ap23-q1a']),('1.6','_chocolate-question.qmd',['ap22-chocolate']),('1.7','_exam-question.qmd',['ap24-q6b-summary','ap24-q6b-outliers']),('1.8','_exam-question.qmd',['ap19-q1-data','ap19-q1-bc']),('1.9','_exam-question.qmd',['ap26-q1-ab','ap26-q1-c'])]:
 sections=[]
 for i in manifest['items']:
  if i['id'] not in ids:continue
  key=i['id'];caption=i['caption'];url=i['source_url'];alt=i['accessible_summary']
  sections.append(f'''<figure class="exam-source" data-exam-id="{key}">
<a class="exam-enlarge" href="assets/exam/{key}.png" aria-label="Enlarge {caption}">
<img src="assets/exam/{key}.png" alt="{caption}. Readable description below." loading="lazy" decoding="async">
</a>
<figcaption>{caption} · <a href="{url}">College Board</a> · © College Board</figcaption>
<details class="exam-description"><summary>Read the question description</summary><p>{alt}</p></details>
</figure>
''')
 (R/f'Unit 1/Topic {topic}'/name).write_text('\n'.join(sections))
for i in manifest['items']:
 p=R/i['output'];p.parent.mkdir(parents=True,exist_ok=True)
 (p.parent/'README.md').write_text('Released-question crops. Rebuild with tools/prepare_exam_figures.py using project/released-exam-figures.json. Source PDFs are not stored here. Keep image descriptions and captions with the lesson.\n')
(R/'site/assets/student-presentation.css').write_text('''main math[display="block"]{display:block;max-width:100%;overflow-x:auto;overflow-y:hidden;padding-block:.2rem}main .math.display{display:block;max-width:100%;overflow-x:auto}.original-practice .original-prompt p,.original-practice label p{display:inline;margin:0}.original-practice math{max-width:100%}.original-nojs>ol>li{margin-bottom:1.5rem}.exam-source{margin:1.4rem 0;padding:1rem;border:1px solid #c5cbd3;border-radius:.5rem;max-width:100%;background:white}.exam-source img{width:100%;height:auto;display:block}.exam-source a.exam-enlarge{display:block;cursor:zoom-in}.exam-source a.exam-enlarge:focus-visible{outline:3px solid #195aa0;outline-offset:4px}.exam-source figcaption{font-size:.86rem;line-height:1.5;text-align:left;margin-top:.65rem}.exam-description{font-size:.9rem;margin-top:.6rem}.exam-description summary{cursor:pointer}.exam-zoom{width:min(95vw,1400px);max-height:94vh;padding:1rem;border:1px solid #777;border-radius:.5rem}.exam-zoom::backdrop{background:rgb(0 0 0 / .65)}.exam-zoom .zoom-bar{position:sticky;top:0;background:white;display:flex;justify-content:space-between;align-items:center;gap:1rem;z-index:1;padding:.4rem}.exam-zoom img{display:block;width:100%;height:auto}.exam-zoom button{padding:.5rem .9rem;min-height:44px}.lesson-sources{margin-top:2rem;font-size:.87rem}.lesson-sources summary{cursor:pointer}@media(max-width:500px){.exam-source{padding:.4rem}.exam-zoom{padding:.3rem;max-width:99vw}}@media print{.exam-source{break-inside:avoid;padding:0;border:0}.exam-zoom{display:none!important}.exam-source img{max-height:220mm;object-fit:contain}}
''')
(R/'site/assets/student-presentation.js').write_text('''(()=>{'use strict';function init(){let active=null;const d=document.createElement('dialog');d.className='exam-zoom';d.setAttribute('aria-label','Enlarged exam question');const bar=document.createElement('div');bar.className='zoom-bar';const title=document.createElement('strong');title.textContent='Exam question';const close=document.createElement('button');close.type='button';close.textContent='Close';const img=document.createElement('img');bar.append(title,close);d.append(bar,img);document.body.append(d);close.addEventListener('click',()=>d.close());d.addEventListener('close',()=>{if(active)active.focus({preventScroll:true});});document.querySelectorAll('a.exam-enlarge').forEach(a=>a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||typeof d.showModal!=='function')return;e.preventDefault();active=a;img.src=a.href;img.alt=a.querySelector('img').alt;title.textContent=a.closest('figure').querySelector('figcaption').textContent;d.showModal();close.focus({preventScroll:true});}));}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
''')
(R/'site/assets/student-presentation.html').write_text('<script src="/site/assets/student-presentation.js" defer></script>\n')
